mapper.select:
/* SQL_ID: RdfClassMapper.selectRangeRdfClassCount */ WITH RECURSIVE class_tree(rdf_class_id, rdf_nmsp_id, rdf_class_nm, rdf_class_desc, rdf_class_logic_nm, rdf_form_mtcds, up_rdf_class_id, rdf_class_regr_id, rdf_class_regr_nm, rdf_class_reg_dt, rdf_class_amdr_id, rdf_class_amdr_nm, rdf_class_amd_dt) AS ( SELECT rdf_class_id, rdf_nmsp_id, rdf_class_nm, rdf_class_desc, rdf_class_logic_nm, rdf_form_mtcds, up_rdf_class_id, rdf_class_regr_id, rdf_class_regr_nm, rdf_class_reg_dt, rdf_class_amdr_id, rdf_class_amdr_nm, rdf_class_amd_dt FROM dtmeta.tb_rdf_class WHERE rdf_class_id IN (SELECT rdf_class_id FROM dtmeta.tb_rdf_propertydefine WHERE rdf_prpty_id = #{rdfPrptyId} AND domn_range_div_mtcd = 'range' ) UNION ALL SELECT c.rdf_class_id, c.rdf_nmsp_id, c.rdf_class_nm, c.rdf_class_desc, c.rdf_class_logic_nm, c.rdf_form_mtcds, c.up_rdf_class_id, c.rdf_class_regr_id, c.rdf_class_regr_nm, c.rdf_class_reg_dt, c.rdf_class_amdr_id, c.rdf_class_amdr_nm, c.rdf_class_amd_dt FROM dtmeta.tb_rdf_class c INNER JOIN class_tree rc ON c.up_rdf_class_id = rc.rdf_class_id ) SELECT COUNT(*) FROM class_tree t1 LEFT JOIN ( SELECT id_all_mtcd.rdf_class_id, string_agg(mtcd_nm, ',') AS mtcd_nm FROM ( SELECT rdf_class_id, unnest(string_to_array(rdf_form_mtcds, ',')) AS each_mtcd FROM dtmeta.tb_rdf_class ORDER BY 1, 2 ) id_all_mtcd LEFT JOIN dtmeta.tb_portal_code ptcd ON id_all_mtcd.each_mtcd = ptcd.mtcd AND ptcd.mtcd_grp_id = 'MCG00009' GROUP BY id_all_mtcd.rdf_class_id ) t2 ON t1.rdf_class_id = t2.rdf_class_id LEFT JOIN dtmeta.tb_rdf_namespace ns ON t1.rdf_nmsp_id = ns.rdf_nmsp_id WHERE 1=1
AND ( t1.rdf_class_nm ILIKE CONCAT('%', #{searchClassNm}, '%') OR t1.rdf_class_logic_nm ILIKE CONCAT('%', #{searchClassNm}, '%') )
AND t1.rdf_nmsp_id = #{rdfNmspId}
AND ( t1.rdf_form_mtcds = #{rdfFormMtcd} OR t1.rdf_form_mtcds LIKE CONCAT('%,', #{rdfFormMtcd}) OR t1.rdf_form_mtcds LIKE CONCAT(#{rdfFormMtcd}, ',%') OR t1.rdf_form_mtcds LIKE CONCAT('%,', #{rdfFormMtcd}, ',%') )

/* SQL_ID: RdfClassMapper.selectRangeRdfClassList */ WITH RECURSIVE class_tree(rdf_class_id, rdf_nmsp_id, rdf_class_nm, rdf_class_desc, rdf_class_logic_nm, rdf_form_mtcds, up_rdf_class_id, rdf_class_regr_id, rdf_class_regr_nm, rdf_class_reg_dt, rdf_class_amdr_id, rdf_class_amdr_nm, rdf_class_amd_dt) AS ( SELECT rdf_class_id, rdf_nmsp_id, rdf_class_nm, rdf_class_desc, rdf_class_logic_nm, rdf_form_mtcds, up_rdf_class_id, rdf_class_regr_id, rdf_class_regr_nm, rdf_class_reg_dt, rdf_class_amdr_id, rdf_class_amdr_nm, rdf_class_amd_dt FROM dtmeta.tb_rdf_class WHERE rdf_class_id IN ( SELECT rdf_class_id FROM dtmeta.tb_rdf_propertydefine WHERE rdf_prpty_id = #{rdfPrptyId} AND domn_range_div_mtcd = 'range' ) UNION ALL SELECT c.rdf_class_id, c.rdf_nmsp_id, c.rdf_class_nm, c.rdf_class_desc, c.rdf_class_logic_nm, c.rdf_form_mtcds, c.up_rdf_class_id, c.rdf_class_regr_id, c.rdf_class_regr_nm, c.rdf_class_reg_dt, c.rdf_class_amdr_id, c.rdf_class_amdr_nm, c.rdf_class_amd_dt FROM dtmeta.tb_rdf_class c INNER JOIN class_tree rc ON c.up_rdf_class_id = rc.rdf_class_id ) SELECT t1.rdf_class_id , (ROW_NUMBER() OVER(ORDER BY t1.rdf_class_nm)) AS rownum , t1.rdf_form_mtcds , t1.rdf_nmsp_id , t1.rdf_class_nm , t1.rdf_class_desc , t1.rdf_class_logic_nm , t1.up_rdf_class_id , t1.rdf_class_regr_id , t1.rdf_class_regr_nm , t1.rdf_class_amdr_id , t1.rdf_class_amdr_nm , t2.mtcd_nm AS rdf_form_mtcd_nm_str , CONCAT( ns.rdf_nmsp_pfix , ':' ,t1.rdf_class_nm ) rdf_class FROM class_tree t1 LEFT JOIN ( SELECT id_all_mtcd.rdf_class_id, string_agg(mtcd_nm, ',') AS mtcd_nm FROM ( SELECT rdf_class_id, unnest(string_to_array(rdf_form_mtcds, ',')) AS each_mtcd FROM dtmeta.tb_rdf_class ORDER BY 1, 2 ) id_all_mtcd LEFT JOIN dtmeta.tb_portal_code ptcd ON id_all_mtcd.each_mtcd = ptcd.mtcd AND ptcd.mtcd_grp_id = 'MCG00009' GROUP BY id_all_mtcd.rdf_class_id ) t2 ON t1.rdf_class_id = t2.rdf_class_id LEFT JOIN dtmeta.tb_rdf_namespace ns ON t1.rdf_nmsp_id = ns.rdf_nmsp_id WHERE 1=1
AND ( t1.rdf_class_nm ILIKE CONCAT('%', #{searchClassNm}, '%') OR t1.rdf_class_logic_nm ILIKE CONCAT('%', #{searchClassNm}, '%') )
AND t1.rdf_nmsp_id = #{rdfNmspId}
AND ( t1.rdf_form_mtcds = #{rdfFormMtcd} OR t1.rdf_form_mtcds LIKE CONCAT('%,', #{rdfFormMtcd}) OR t1.rdf_form_mtcds LIKE CONCAT(#{rdfFormMtcd}, ',%') OR t1.rdf_form_mtcds LIKE CONCAT('%,', #{rdfFormMtcd}, ',%') )
ORDER BY t1.rdf_class_nm

mapper.update:
UPDATE dtmeta.tb_rdf_class   /* SQL_ID: RdfClassMapper.updateRdfClass */
SET
    rdf_nmsp_id = #{rdfNmspId}
    , rdf_class_nm = #{rdfClassNm}
    , rdf_class_desc = #{rdfClassDesc}
    , rdf_class_logic_nm = #{rdfClassLogicNm}
    , rdf_class_amd_dt = current_timestamp
    , rdf_class_amdr_id = #{rdfClassAmdrId}
    , rdf_class_amdr_nm = #{rdfClassAmdrNm}
    , up_rdf_class_id = #{upRdfClassId}
    , rdf_form_mtcds = #{rdfFormMtcds}
WHERE rdf_class_id = #{rdfClassId}

mapper.delete:
DELETE   /* SQL_ID: RdfClassMapper.deleteRdfClass */
FROM dtmeta.tb_rdf_class
WHERE rdf_class_id = #{rdfClassId}

