SELECT EXISTS (  /* SQL_ID: RdfClassMapper.validationDuringEditMode */
    SELECT 1
    FROM dtmeta.tb_rdf_class
    WHERE rdf_class_id != #{rdfClassId} AND rdf_nmsp_id = #{rdfNmspId} AND rdf_class_nm = #{rdfClassNm}
)

SELECT EXISTS (  /* SQL_ID: RdfClassMapper.validationDuringModifyMode */
    SELECT 1
    FROM dtmeta.tb_rdf_class
    WHERE rdf_class_id != #{rdfClassId} AND rdf_nmsp_id = #{rdfNmspId} AND rdf_class_nm = #{rdfClassNm}
)

SELECT EXISTS (  /* SQL_ID: RdfClassMapper.isRdfNmspIdExist */
    SELECT 1
    FROM dtmeta.tb_rdf_namespace
    WHERE rdf_nmsp_id = #{rdfNmspId}
)

SELECT EXISTS (  /* SQL_ID: RdfClassMapper.validationDuringDeleteMode */
    SELECT 1
    FROM dtmeta.tb_rdf_propertydefine
    WHERE rdf_class_id = #{rdfClassId}
)
OR EXISTS (
    SELECT 1
    FROM dtmeta.tb_rdf_mappingmodel
    WHERE rdf_class_id = #{rdfClassId}
)
OR EXISTS (
    SELECT 1
    FROM dtmeta.tb_rdf_mappingrule
    WHERE objt_rdf_class_id = #{rdfClassId}
)
